import{_ as n,o as a,c as l,a2 as p}from"./chunks/framework.BDmrrkGR.js";const b=JSON.parse('{"title":"二分查找 — LeetCode 704","description":"","frontmatter":{"title":"二分查找 — LeetCode 704","date":"2026-07-29T00:00:00.000Z","tags":["二分查找","LeetCode","华为高频","简单"],"category":"leetcode","difficulty":"简单","leetcodeId":704,"excerpt":"二分查找。"},"headers":[],"relativePath":"posts/leetcode/code704-binary-search.md","filePath":"posts/leetcode/code704-binary-search.md","lastUpdated":1789257371000}'),e={name:"posts/leetcode/code704-binary-search.md"};function o(t,s,r,c,i,y){return a(),l("div",null,[...s[0]||(s[0]=[p(`<h1 id="二分查找" tabindex="-1">二分查找 <a class="header-anchor" href="#二分查找" aria-label="Permalink to &quot;二分查找&quot;">​</a></h1><h2 id="题目描述" tabindex="-1">题目描述 <a class="header-anchor" href="#题目描述" aria-label="Permalink to &quot;题目描述&quot;">​</a></h2><p>给定一个按升序排列且不含重复元素的整数数组 <code>nums</code> 和目标值 <code>target</code>，如果目标值存在，返回它的下标；否则返回 <code>-1</code>。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>输入: nums = [-1,0,3,5,9,12], target = 9</span></span>
<span class="line"><span>输出: 4</span></span>
<span class="line"><span>解释: 9 出现在 nums 中并且下标为 4。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="代码实现" tabindex="-1">代码实现 <a class="header-anchor" href="#代码实现" aria-label="Permalink to &quot;代码实现&quot;">​</a></h2><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="color:#C678DD;">package</span><span style="color:#C678DD;"> huawei</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">/*</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * 【原理说明 - 标准二分查找（左闭右闭区间）】</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * 1. 二分查找要求数组有序（本题为升序）。</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * 2. 维护搜索区间 [left, right]，初始为 [0, n-1]。</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * 3. 每次取中间位置 mid = left + (right - left) / 2，比较 nums[mid] 与 target：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *    - 若相等，返回 mid。</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *    - 若 nums[mid] &lt; target，说明目标在右半部分，left = mid + 1。</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *    - 若 nums[mid] &gt; target，说明目标在左半部分，right = mid - 1。</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * 4. 循环条件为 left &lt;= right，因为区间左右闭合，当 left == right 时仍需检查该位置。</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * 5. 若循环结束仍未找到，返回 -1。</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * 6. 时间复杂度 O(log n)，空间复杂度 O(1)。</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> */</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">class</span><span style="color:#E5C07B;"> Solution</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    public</span><span style="color:#C678DD;"> int</span><span style="color:#61AFEF;"> search</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">int</span><span style="color:#ABB2BF;">[] </span><span style="color:#E06C75;font-style:italic;">nums</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">int</span><span style="color:#E06C75;font-style:italic;"> target</span><span style="color:#ABB2BF;">)</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 1. 初始化左右指针，区间为 [left, right]</span></span>
<span class="line"><span style="color:#C678DD;">        int</span><span style="color:#E06C75;"> left</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        int</span><span style="color:#E06C75;"> right</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> nums</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">length</span><span style="color:#56B6C2;"> -</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 2. 当区间不为空时，继续查找</span></span>
<span class="line"><span style="color:#C678DD;">        while</span><span style="color:#ABB2BF;"> (left </span><span style="color:#56B6C2;">&lt;=</span><span style="color:#ABB2BF;"> right) {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">            // 3. 计算中间位置，防止 left + right 溢出</span></span>
<span class="line"><span style="color:#C678DD;">            int</span><span style="color:#E06C75;"> mid</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> left </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> (right </span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;"> left) </span><span style="color:#56B6C2;">/</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">            // 4. 比较中间值与目标值</span></span>
<span class="line"><span style="color:#C678DD;">            if</span><span style="color:#ABB2BF;"> (nums[mid] </span><span style="color:#56B6C2;">==</span><span style="color:#ABB2BF;"> target) {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">                // 找到了，返回下标</span></span>
<span class="line"><span style="color:#C678DD;">                return</span><span style="color:#ABB2BF;"> mid;</span></span>
<span class="line"><span style="color:#ABB2BF;">            } </span><span style="color:#C678DD;">else</span><span style="color:#C678DD;"> if</span><span style="color:#ABB2BF;"> (nums[mid] </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;"> target) {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">                // 目标在右半部分，左指针右移</span></span>
<span class="line"><span style="color:#ABB2BF;">                left </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> mid </span><span style="color:#56B6C2;">+</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">            } </span><span style="color:#C678DD;">else</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">                // 目标在左半部分，右指针左移</span></span>
<span class="line"><span style="color:#ABB2BF;">                right </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> mid </span><span style="color:#56B6C2;">-</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">            }</span></span>
<span class="line"><span style="color:#ABB2BF;">        }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 5. 未找到，返回 -1</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#56B6C2;"> -</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br></div></div>`,7)])])}const m=n(e,[["render",o]]);export{b as __pageData,m as default};
